export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored. Internal columns never leave the server. */
export interface JobRow {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The job representation returned by every endpoint. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const MAX_INPUT_LENGTH = 1000;
export const STEP_RANGE = { min: 1, max: 20 } as const;
export const FAIL_ATTEMPTS_RANGE = { min: 0, max: 5 } as const;

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

export function toPublicJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function isJsonContentType(contentType: string | undefined): boolean {
  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  return mediaType === 'application/json';
}

function isIntegerIn(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

/** Validates the JSON body. Returns either a normalized submission or the field errors. */
export function validateBody(contentType: string | undefined, text: string): { value?: Submission; errors: FieldError[] } {
  if (!isJsonContentType(contentType)) {
    return { errors: [{ field: 'body', message: 'Content-Type must be application/json' }] };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { errors: [{ field: 'body', message: 'Body must be valid JSON' }] };
  }
  if (!isPlainObject(parsed)) {
    return { errors: [{ field: 'body', message: 'Body must be a JSON object' }] };
  }

  const errors: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!KNOWN_FIELDS.has(key)) errors.push({ field: key, message: 'Unknown field' });
  }

  let input = '';
  if (!Object.hasOwn(parsed, 'input')) {
    errors.push({ field: 'input', message: 'input is required' });
  } else if (typeof parsed.input !== 'string') {
    errors.push({ field: 'input', message: 'input must be a string' });
  } else if (parsed.input.length < 1 || parsed.input.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (parsed.input.trim() === '') {
    errors.push({ field: 'input', message: 'input must not be blank' });
  } else {
    input = parsed.input;
  }

  let steps = DEFAULT_STEPS;
  if (Object.hasOwn(parsed, 'steps')) {
    if (isIntegerIn(parsed.steps, STEP_RANGE.min, STEP_RANGE.max)) steps = parsed.steps;
    else errors.push({ field: 'steps', message: `steps must be an integer from ${STEP_RANGE.min} to ${STEP_RANGE.max}` });
  }

  let failAttempts = DEFAULT_FAIL_ATTEMPTS;
  if (Object.hasOwn(parsed, 'failAttempts')) {
    if (isIntegerIn(parsed.failAttempts, FAIL_ATTEMPTS_RANGE.min, FAIL_ATTEMPTS_RANGE.max)) failAttempts = parsed.failAttempts;
    else errors.push({ field: 'failAttempts', message: `failAttempts must be an integer from ${FAIL_ATTEMPTS_RANGE.min} to ${FAIL_ATTEMPTS_RANGE.max}` });
  }

  if (errors.length > 0) return { errors };
  return { value: { input, steps, failAttempts }, errors };
}

/** Validates the optional Idempotency-Key header. */
export function validateIdempotencyKey(header: string | string[] | undefined): { key: string | null; errors: FieldError[] } {
  if (header === undefined) return { key: null, errors: [] };
  const value = Array.isArray(header) ? undefined : header;
  if (value === undefined || !IDEMPOTENCY_KEY_PATTERN.test(value)) {
    return {
      key: null,
      errors: [{ field: 'Idempotency-Key', message: 'Idempotency-Key must be 1 to 128 characters of letters, digits, "_" or "-", given once' }],
    };
  }
  return { key: value, errors: [] };
}

