import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import type { JobRow } from './jobs.ts';

const SCHEMA = `
  CREATE TABLE IF NOT EXISTS jobs (
    seq INTEGER PRIMARY KEY AUTOINCREMENT,
    id TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
    input TEXT NOT NULL,
    steps INTEGER NOT NULL,
    fail_attempts INTEGER NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    completed INTEGER NOT NULL DEFAULT 0,
    output TEXT,
    error TEXT,
    idempotency_key TEXT UNIQUE,
    available_at INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, available_at, seq);
  CREATE TABLE IF NOT EXISTS worker_heartbeat (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    last_seen INTEGER NOT NULL
  );
`;

/**
 * Opens the SQLite database shared by the server and worker processes and creates the schema.
 * Both processes call this independently; every statement is idempotent.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  transaction(db, () => db.exec(SCHEMA));
  return db;
}

/** Runs `fn` inside a BEGIN IMMEDIATE transaction, committing on success and rolling back on error. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let value: T;
  try {
    value = fn();
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open any more
    }
    throw e;
  }
  return value;
}

export function insertJob(db: DatabaseSync, row: JobRow): void {
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error,
                       idempotency_key, available_at, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    row.id,
    row.status,
    row.input,
    row.steps,
    row.fail_attempts,
    row.attempts,
    row.completed,
    row.output,
    row.error,
    row.idempotency_key,
    row.available_at,
    row.created_at,
    row.updated_at,
  );
}

export function findJobById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function findJobByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

/** All jobs, newest first (by insertion sequence, so identical timestamps keep their order). */
export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

// ---- Worker heartbeat ----

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, last_seen) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET last_seen = excluded.last_seen',
  ).run(now);
}

export function readHeartbeat(db: DatabaseSync): number | undefined {
  const row = db.prepare('SELECT last_seen FROM worker_heartbeat WHERE id = 1').get() as { last_seen: number } | undefined;
  return row?.last_seen;
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat WHERE id = 1').run();
}

// ---- Worker job transitions ----

/**
 * Picks the next job to process, in one short transaction.
 * A job left `running` (by a worker that stopped mid-attempt) is returned first, with its attempt
 * count unchanged and progress reset: the interrupted attempt is replayed from its first step.
 * Otherwise the oldest queued job whose retry delay has elapsed is claimed as a new attempt.
 */
export function claimNext(db: DatabaseSync, now: number, nowIso: string): JobRow | undefined {
  return transaction(db, () => {
    const interrupted = db.prepare("SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1").get() as unknown as JobRow | undefined;
    if (interrupted) {
      db.prepare('UPDATE jobs SET completed = 0, updated_at = ? WHERE id = ?').run(nowIso, interrupted.id);
      return { ...interrupted, completed: 0, updated_at: nowIso };
    }
    const next = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1")
      .get(now) as unknown as JobRow | undefined;
    if (!next) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL, updated_at = ? WHERE id = ?",
    ).run(nowIso, next.id);
    return { ...next, status: 'running', attempts: next.attempts + 1, completed: 0, output: null, error: null, updated_at: nowIso };
  });
}

export function recordProgress(db: DatabaseSync, id: string, completed: number, nowIso: string): void {
  db.prepare("UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(completed, nowIso, id);
}

export function requeueForRetry(db: DatabaseSync, id: string, availableAt: number, nowIso: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(availableAt, nowIso, id);
}

export function failJob(db: DatabaseSync, id: string, error: string, nowIso: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(error, nowIso, id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, nowIso: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(output, nowIso, id);
}

