import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { clearHeartbeat as _unused } from './db.ts';
import { findJobById, findJobByKey, insertJob, listJobs, openDatabase, readHeartbeat, transaction } from './db.ts';
import { toPublicJob, validateBody, validateIdempotencyKey, type FieldError, type JobRow, type Submission } from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** A worker heartbeat older than this means the worker is down. */
const WORKER_STALE_MS = 3000;
/** Largest request body accepted; far above any valid submission. */
const MAX_BODY_BYTES = 1024 * 1024;
/** Time allowed for in-flight requests to finish on shutdown before connections are dropped. */
const SHUTDOWN_GRACE_MS = 3000;

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  sendJson(res, status, { error: fields ? { code, message, fields } : { code, message } }, headers);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const idem = validateIdempotencyKey(req.headers['idempotency-key']);
  const body = tooLarge
    ? { value: undefined, errors: [{ field: 'body', message: 'Request body is too large' }] as FieldError[] }
    : validateBody(req.headers['content-type'], text);
  const errors = [...body.errors, ...idem.errors];
  if (errors.length > 0 || !body.value) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }
  const submission: Submission = body.value;

  type Outcome = { kind: 'created' | 'replayed'; job: JobRow } | { kind: 'conflict' };
  const outcome: Outcome = transaction(db, (): Outcome => {
    if (idem.key !== null) {
      const existing = findJobByKey(db, idem.key);
      if (existing) {
        const same =
          existing.input === submission.input &&
          existing.steps === submission.steps &&
          existing.fail_attempts === submission.failAttempts;
        return same ? { kind: 'replayed', job: existing } : { kind: 'conflict' };
      }
    }
    const now = new Date().toISOString();
    const row: JobRow = {
      id: randomUUID(),
      status: 'queued',
      input: submission.input,
      steps: submission.steps,
      fail_attempts: submission.failAttempts,
      attempts: 0,
      completed: 0,
      output: null,
      error: null,
      idempotency_key: idem.key,
      available_at: Date.now(),
      created_at: now,
      updated_at: now,
    };
    insertJob(db, row);
    return { kind: 'created', job: row };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toPublicJob(outcome.job));
}

function handleList(res: ServerResponse): void {
  sendJson(res, 200, { jobs: listJobs(db).map(toPublicJob) });
}

function handleGet(res: ServerResponse, id: string): void {
  const row = findJobById(db, id);
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  sendJson(res, 200, toPublicJob(row));
}

function handleHealth(res: ServerResponse): void {
  const lastSeen = readHeartbeat(db);
  const up = lastSeen !== undefined && Date.now() - lastSeen <= WORKER_STALE_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  const methodNotAllowed = (allowed: string[]) =>
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`, undefined, { allow: allowed.join(', ') });

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(['GET']);
    return handleHealth(res);
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(['GET']);
    return handleGet(res, decodeURIComponent(match[1]!));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let finished = false;
function finish(): void {
  if (finished) return;
  finished = true;
  try {
    db.close();
  } catch {
    // already closed
  }
  process.exit(0);
}

function shutdown(): void {
  // Stop accepting connections; let active requests finish, but do not wait forever for stalled clients.
  server.close(finish);
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS).unref();
  setTimeout(finish, SHUTDOWN_GRACE_MS * 2).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.on('error', (err) => {
  console.error('server error:', err);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

