/** Delay before a failed attempt is retried (between the 250 ms and 2 s bounds). */
const RETRY_DELAY_MS = 500;
/** Total attempts before a job with transient failures is marked failed. */
const MAX_ATTEMPTS = 3;
/** The simulated transient failure message stored on failed jobs. */
const TRANSIENT_ERROR = 'transient failure';

const db = openDatabase();
const shutdown = new AbortController();
let stopping = false;

function requestStop(): void {
  if (stopping) return;
  stopping = true;
  shutdown.abort();
}
process.on('SIGTERM', requestStop);
process.on('SIGINT', requestStop);

/** Waits for `ms`, returning early (without error) when shutdown has been requested. */
async function pause(ms: number): Promise<void> {
  try {
    await sleep(ms, undefined, { signal: shutdown.signal });
  } catch {
    // aborted: the caller checks `stopping`
  }
}

/**
 * Runs one attempt of a job. The attempt number is `job.attempts`, as already counted when the
 * attempt was claimed (or, for an interrupted attempt, as counted before the worker stopped).
 */
async function processAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fail at the first step, before any progress is recorded.
    await pause(STEP_MS);
    if (stopping) return;
    const now = new Date().toISOString();
    if (attempt < MAX_ATTEMPTS) requeueForRetry(db, job.id, Date.now() + RETRY_DELAY_MS, now);
    else failJob(db, job.id, TRANSIENT_ERROR, now);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await pause(STEP_MS);
    // A stopped worker leaves the job `running`; recovery replays this attempt from its first step.
    if (stopping) return;
    recordProgress(db, job.id, step, new Date().toISOString());
  }
  completeJob(db, job.id, job.input.toUpperCase(), new Date().toISOString());
}

async function main(): Promise<void> {
  // Heartbeat immediately, then periodically (also during idle polls, step waits and retry waits).
  writeHeartbeat(db, Date.now());
  const heartbeat = every(HEARTBEAT_MS);
  const beating = (async () => {
    for await (const _ of heartbeat) {
      try {
        writeHeartbeat(db, Date.now());
      } catch (err) {
        console.error('heartbeat failed:', err);
      }
    }
  })();

  console.log('worker started');
  try {
    while (!stopping) {
      let job: JobRow | undefined;
      try {
        job = claimNext(db, Date.now(), new Date().toISOString());
      } catch (err) {
        console.error('claim failed:', err);
      }
      if (!job) {
        await pause(POLL_MS);
