      }
      try {
        await processAttempt(job);
      } catch (err) {
        console.error(`processing job ${job.id} failed:`, err);
        await pause(POLL_MS);
      }
    }
  } finally {
    heartbeat.return?.();
    await beating;
    try {
      clearHeartbeat(db);
    } catch {
      // database unavailable; the heartbeat will expire anyway
    }
    db.close();
    console.log('worker stopped');
  }
}

main().then(
  () => process.exit(0),
  (err: unknown) => {
    console.error('worker failed:', err);
    process.exit(1);
